const introducedPaths = nulPaths(git(repoRoot, ['diff', '--name-only', '--no-relative', '-z', `${base}..${branch}`], { maxBuffer: GIT_LIST_MAX_BUFFER }))
  .filter((p) => p !== '.fgos' && !p.startsWith('.fgos/'));
if (introducedPaths.length === 0) {
  return [];
}

